package pages; import org.openqa.selenium.*; import org.openqa.selenium.support.ui.Select; public class BlazeDemoPage {private final WebDriver d; public BlazeDemoPage(WebDriver d){this.d=d;} public void search(String from,String to){new Select(d.findElement(By.name("fromPort"))).selectByVisibleText(from);new Select(d.findElement(By.name("toPort"))).selectByVisibleText(to);d.findElement(By.cssSelector("input[type='submit']")).click();} public void chooseFirstFlight(){d.findElement(By.cssSelector("input[type='submit']")).click();} public void enterPassenger(String name,String address,String city,String state,String zip,String card,String cardName){d.findElement(By.id("inputName")).sendKeys(name);d.findElement(By.id("address")).sendKeys(address);d.findElement(By.id("city")).sendKeys(city);d.findElement(By.id("state")).sendKeys(state);d.findElement(By.id("zipCode")).sendKeys(zip);d.findElement(By.id("creditCardNumber")).sendKeys(card);d.findElement(By.id("nameOnCard")).sendKeys(cardName);} public void purchase(){d.findElement(By.cssSelector("input[type='submit']")).click();}}